    for (const r of [0.38, 0.62, 0.84]) { c.beginPath(); c.arc(cx, cy, R * r, 0, TAU); c.stroke(); }
    c.save(); c.beginPath(); c.arc(cx, cy, R * 0.97, 0, TAU); c.clip();
