    for (const gz of [0.5, -0.7]) { const ln = new THREE.Mesh(new THREE.BoxGeometry(0.006, beltF(gz) - 0.42, 0.008), gapMat); ln.position.set(s * (hwF(gz) + 0.001), (beltF(gz) + 0.4) / 2, gz); ln.rotation.x = gz > 0 ? -0.06 : 0.04; car.add(ln); }
