  const gcc = new THREE.Mesh(new THREE.CylinderGeometry(0.044, 0.044, 0.034, 20), LowMats.gold); gcc.geometry.rotateX(Math.PI / 2); onRear(gcc, 0, 0.775, 0.02);
  const lettTex = canvasTex(256, 48, (c, w, h) => { c.fillStyle = '#e8e8ec'; c.font = 'bold 40px Arial'; c.textAlign = 'center'; c.textBaseline = 'middle'; c.fillText('GT 500', w / 2, h / 2 + 2); });
  onRear(new THREE.Mesh(new THREE.PlaneGeometry(0.16, 0.03), new THREE.MeshStandardMaterial({ map: lettTex, transparent: true, metalness: 0.7, roughness: 0.3, envMap: LowMats.chromeEnv })), -0.3, 0.93, 0.004);
