      const i = py * W + px, lx = clamp(px - xi, 0, x1 - xi - 1e-3), k = Math.floor(lx / sw), sx = (lx - k * sw) / sw;
      seg[i] = px < xi ? -1 : sx; loc[i] = px < xi ? (px - x0) / (xi - x0) : sx;   // position across its own section
      let h, z;
