// plan path for a bumper wrapping a body corner: left side -> round the corner -> across -> right side
function wrapPath(hw, z0, dir, rc = 0.12, wrap = 0.3, nArc = 7, nMid = 14) {
  const xs = hw - rc, cz = z0 - dir * rc, P = [];
  for (let k = 0; k < 3; k++) P.push([-hw, cz - dir * wrap * (1 - k / 3)]);
  for (let k = 0; k <= nArc; k++) { const a = Math.PI / 2 * k / nArc; P.push([-xs - rc * Math.cos(a), cz + dir * rc * Math.sin(a)]); }
  for (let k = 1; k < nMid; k++) P.push([lerp(-xs, xs, k / nMid), z0]);
  for (let k = 0; k <= nArc; k++) { const a = Math.PI / 2 * (1 - k / nArc); P.push([xs + rc * Math.cos(a), cz + dir * rc * Math.sin(a)]); }
  for (let k = 1; k <= 3; k++) P.push([hw, cz - dir * wrap * k / 3]);
  return P;
}
const scaleProf = (p, sx, sy) => p.map(([o, y]) => [o * sx, y * sy]);
function ribLensTex(lit) {
  return canvasTex(128, 64, (c, w, h) => {
    const g = c.createLinearGradient(0, 0, 0, h); g.addColorStop(0, lit ? '#ff6a50' : '#7a0c12'); g.addColorStop(0.5, lit ? '#ff2a1a' : '#5a070c'); g.addColorStop(1, lit ? '#d81810' : '#3c0508');
    c.fillStyle = g; c.fillRect(0, 0, w, h);
    for (let y = 0; y < h; y += 6) { c.fillStyle = lit ? 'rgba(255,220,200,0.25)' : 'rgba(255,120,110,0.18)'; c.fillRect(0, y, w, 2); }
    for (let x = 0; x < w; x += 16) { c.fillStyle = 'rgba(0,0,0,0.18)'; c.fillRect(x, 0, 2, h); }
  });
}
