  const crown = new THREE.Mesh(new THREE.CylinderGeometry(5.2, 5.2, 2.4, 16), deckMats().stuntBarrier); crown.position.set(C.x, top + 0.6, C.z); scene.add(crown);
  // spiral sign
  const tex = canvasTex(512, 160, (c, w, h) => { c.fillStyle = '#14213d'; c.fillRect(0, 0, w, h); c.fillStyle = '#ffd166'; c.font = 'bold 74px Arial'; c.textAlign = 'center'; c.fillText('SPIRAL JUMP', w / 2, 100); c.fillStyle = '#ff3d8f'; c.fillRect(0, h - 22, w, 14); });
  const sign = new THREE.Mesh(new THREE.BoxGeometry(14, 4.4, 0.4), new THREE.MeshLambertMaterial({ map: tex })); sign.position.set(C.x, top + 4.6, C.z); scene.add(sign);
