    for (let e = 0; e < 4; e++) { const [ax, az] = edge[e], [bx, bz] = edge[e + 1], L2 = Math.hypot(bx - ax, bz - az), n = Math.round(L2 / 3.2); let prev = null;
      for (let k = 0; k <= n; k++) { const x = lerp(ax, bx, k / n), z = lerp(az, bz, k / n); if (!clearOfRoads(x, z, 2.5)) { prev = null; continue; } const p = { x, z, y: groundHeight(x, z) }; posts.push(p); if (prev) rails.push([prev, p]); prev = p; } }
