    const birds = []; homes.forEach(h => { for (let k = 0; k < h.n; k++) birds.push({ h, ph: rng() * TAU, sp: (0.25 + rng() * 0.2) * (rng() < 0.5 ? 1 : -1), rr: h.r * (0.6 + rng() * 0.6), dy: (rng() - 0.5) * 14, fl: 6 + rng() * 3, fo: rng() * 10 }); });
