  const mat = Sky.moonMat = moonMaterial();
  const cap = new THREE.Mesh(cg, mat); cap.receiveShadow = true; scene.add(cap);
  const body = new THREE.Mesh(sg, mat); scene.add(body);
  // a lander and a flag by the big crater, and some boulders
  const at = (r, th) => { const x = MOON.x + Math.cos(th) * r, z = MOON.z + Math.sin(th) * r; return [x, moonSurfaceY(x, z), z]; };
  const [lx, ly, lz] = at(19.5, 0.5), L = new THREE.Group(); L.position.set(lx, ly, lz); L.rotation.y = 0.4; scene.add(L);
  const gold = new THREE.MeshStandardMaterial({ color: 0xd9a63a, metalness: 0.75, roughness: 0.35 }), silv = new THREE.MeshStandardMaterial({ color: 0xc9ced6, metalness: 0.6, roughness: 0.3 }), dark = new THREE.MeshLambertMaterial({ color: 0x2a2d33 });
  const addL = (geo, m2, x, y, z, rx = 0, rz = 0) => { const o = new THREE.Mesh(geo, m2); o.position.set(x, y, z); o.rotation.set(rx, 0, rz); o.castShadow = true; L.add(o); return o; };
  addL(new THREE.CylinderGeometry(2.2, 2.2, 1.7, 8), gold, 0, 2.0, 0);
  addL(new THREE.BoxGeometry(2.6, 2.0, 2.6), silv, 0, 3.8, 0); addL(new THREE.CylinderGeometry(0.9, 0.9, 0.5, 10), silv, 0, 5.0, 0);
  addL(new THREE.BoxGeometry(0.7, 0.7, 0.1), dark, 0, 3.9, 1.32); addL(new THREE.ConeGeometry(0.6, 0.8, 10), dark, 0, 0.9, 0);
  for (let k = 0; k < 4; k++) { const a = k / 4 * TAU + Math.PI / 4; addL(new THREE.CylinderGeometry(0.08, 0.08, 2.6, 5), silv, Math.cos(a) * 2.4, 1.1, Math.sin(a) * 2.4, Math.sin(a) * 0.45, -Math.cos(a) * 0.45); addL(new THREE.CylinderGeometry(0.42, 0.42, 0.08, 10), silv, Math.cos(a) * 3.0, 0.05, Math.sin(a) * 3.0); }
  World.colliders.add({ type: 'circle', x: lx, z: lz, r: 3.4, y0: ly - 1, y1: ly + 5.5 });
  const [fx, fy, fz] = at(23, 0.82);
  const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 4.2, 6), silv); pole.position.set(fx, fy + 2.1, fz); scene.add(pole);
  const flagTex = canvasTex(128, 80, (c, w, h) => { c.fillStyle = '#e0186e'; c.fillRect(0, 0, w, h); c.fillStyle = '#fff4e0'; c.font = 'bold 40px Arial'; c.textAlign = 'center'; c.fillText('67', w / 2, 56); });
  const flag = new THREE.Mesh(new THREE.PlaneGeometry(2.2, 1.35), new THREE.MeshLambertMaterial({ map: flagTex, side: THREE.DoubleSide })); flag.position.set(fx + 1.1, fy + 3.5, fz); scene.add(flag); // no wind up here: it just hangs out stiff
  World.colliders.add({ type: 'circle', x: fx, z: fz, r: 0.3, y0: fy - 1, y1: fy + 4.5 });
  const rocks = [], rr = makeRng(31);
  for (let k = 0; k < 70; k++) { const r = 8 + rr() * 72, th = rr() * TAU, [x, y, z] = at(r, th); if (Decks.list.some(dd => dd.sky && dd.samples.some(p => Math.hypot(p.x - x, p.z - z) < (dd.halfW || 6) + 2.5))) continue; rocks.push([x, y, z, 0.3 + rr() * 1.1]); }
