    const night = L.moon ? 1 : 0; for (const k of ['cloud', 'bridge', 'launch', 'chute']) if (SkyMats[k]) SkyMats[k].emissiveIntensity = 0.45 + 0.6 * night;
    if (SkyMats.rail) SkyMats.rail.emissiveIntensity = 0.5 + 0.8 * night;
    Sound.space = smooth(MOON.R + 60, MOON.R + 8, Math.hypot(P.pos.x - MOON.x, P.pos.y - MOON.y, P.pos.z - MOON.z)) * (P.pos.y > MOON.y ? 1 : 0);
