    // --- rain streaks (a box of drops that follows the camera) ---
    const N = 3600, pos = new Float32Array(N * 6); this.drops = { N, pos, off: new Float32Array(N * 3) };
    for (let i = 0; i < N; i++) { this.drops.off[i * 3] = Math.random() * 80; this.drops.off[i * 3 + 1] = Math.random() * 40; this.drops.off[i * 3 + 2] = Math.random() * 80; }
