      for (let a = 0; a <= 9; a++) { const t = a / 9 * Math.PI / 2; c.beginPath(); c.moveTo(cx, cy); c.lineTo(cx + Math.cos(t) * 124, cy + Math.sin(t) * 124); c.stroke(); }
