      const [L, Y] = R[left ? n - 6 : 5]; webs.push({ p: this.worldPt(p, L * 0.97, Y - 0.6), yaw: Math.atan2(p.tx, p.tz) + (left ? -0.5 : 0.5) * Math.PI * 0.5, s: 2.5 + rng() * 2.5, left });
