    const ctx = this.ctx, bus = ctx.createGain(); bus.gain.value = 0.9;
    const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 6000; lp.Q.value = 0.5;
    bus.connect(lp).connect(this.comp);
