    const ground = 1 - (typeof Sky !== 'undefined' ? Sky.kAlt : 0); // surf and birds fade out as you climb into the sky
    if (L.surf) L.surf.g.gain.setTargetAtTime(A.coast * 0.55 * L.surf.k * ground, t, 0.8);
