    const t = this.ctx.currentTime, s = this.ctx.createBufferSource(); s.buffer = this.nb;
    const f = this.ctx.createBiquadFilter(); f.type = 'bandpass'; f.Q.value = 0.9; f.frequency.setValueAtTime(5200, t); f.frequency.exponentialRampToValueAtTime(1400, t + 0.35);
