      let lo = S[0], hi = S[S.length - 1];
      for (let i = 0; i < S.length - 1; i++) if (rpm >= S[i].rpm && rpm <= S[i + 1].rpm) { lo = S[i]; hi = S[i + 1]; }
      if (rpm <= S[0].rpm) { lo = hi = S[0]; } else if (rpm >= S[S.length - 1].rpm) { lo = hi = S[S.length - 1]; }
