    if (W.held === null && W.ang !== 0) { W.ang *= Math.exp(-13 * dt); if (Math.abs(W.ang) < 0.4) W.ang = 0; }
    if (Math.abs(W.ang - W.shown) > 0.05 && W.rot) { W.shown = W.ang; W.rot.style.transform = 'rotate(' + W.ang.toFixed(1) + 'deg)'; }
