    let brake = (k.has('KeyS') || k.has('ArrowDown')) ? 1 : 0;
    let sKb = ((k.has('KeyD') || k.has('ArrowRight')) ? 1 : 0) - ((k.has('KeyA') || k.has('ArrowLeft')) ? 1 : 0);
    let hb = k.has('Space') ? 1 : 0;
    let nos = (k.has('ShiftLeft') || k.has('ShiftRight') || k.has('KeyN')) ? 1 : 0; // NOS: hold Shift (or N)
    // smooth keyboard steering for a gentler analog feel
