    const L = this.race.length;
    for (const a of this.ai) {
      const V = a.veh;
      if (a.finished) { V.update(dt, { throttle: 0, brake: 0.6, steer: 0, handbrake: V.speed < 2 }); continue; }
      const q = routeProgress(this.route, V.pos.x, V.pos.z, a.i, 40, V.pos.y); a.i = q.i; a.s = q.s;
      const spd = V.speed;
      // rubber band against the player
      const gap = a.s - this.playerS;
      if (a.prevGap !== null && a.prevGap > 0 && gap <= 0 && this.state === 'racing') a.passedT = 3; // you just got past
      a.prevGap = gap; a.passedT = Math.max(0, a.passedT - dt);
      let rb = 1; if (this.state === 'racing') { if (gap > 40) rb = lerp(1, 0.84, smooth(40, 180, gap)); else if (gap < -30) rb = lerp(1, 1.12, smooth(-30, -160, gap)); }
      const look = 7 + spd * 0.5;
      let lane = a.lane;
      // avoid the player & each other
      for (const o of [P, ...this.ai.map(x => x.veh)]) {
        if (o === V) continue;
        const dx = o.pos.x - V.pos.x, dz = o.pos.z - V.pos.z, d = Math.hypot(dx, dz);
        if (d < 14) { const fwd = dx * Math.sin(V.heading) + dz * Math.cos(V.heading); if (fwd > 0) { const left = dx * Math.cos(V.heading) - dz * Math.sin(V.heading); lane += (left > 0 ? -1 : 1) * 2.2 * (1 - d / 14); } }
      }
      const tp = routeAt(this.route, a.s + look);
      const hw = Math.max(tp.halfW - 1.4, 0.5); lane = clamp(lane, -hw, hw);
      const tx = tp.x - tp.tz * lane, tz = tp.z + tp.tx * lane; // +lane = left of travel
      const dx = tx - V.pos.x, dz = tz - V.pos.z;
      const fwd = dx * Math.sin(V.heading) + dz * Math.cos(V.heading), left = dx * Math.cos(V.heading) - dz * Math.sin(V.heading);
      const ang = Math.atan2(left, Math.max(fwd, 0.1));
      const steer = clamp(-ang * 2.4, -1, 1);
      const vt = Math.min(routeAt(this.route, a.s + 4 + spd * 0.35).v, routeAt(this.route, a.s).v + 6) * a.skill * rb * (this.state === 'finished' ? 0.6 : 1);
      // NOS: only where the road ahead is fast and straight, and each rival has a habit
      const straight = Math.min(routeAt(this.route, a.s + 20).v, routeAt(this.route, a.s + 70).v, routeAt(this.route, a.s + 130).v) > 41 && !tp.gap;
      let nos = false;
      if (this.state === 'racing' && straight && V.nos > 0.06) {
        const style = a.rv.nos, frac = a.s / L;
        if (style === 'steady') nos = V.nosOn || V.nos > 0.45;
        else if (style === 'hothead') nos = V.nosOn || a.passedT > 0 || (gap < 0 && gap > -18);
        else if (style === 'closer') nos = frac > 0.68;
      }
      let vt2 = vt; if (nos) vt2 = vt + 14; else if (V.form === 'orb' && straight && this.state === 'racing') vt2 = vt + 6; // orbs are quicker on the straights
      let throttle = 0, brake = 0;
      if (spd < vt2 - 0.5) throttle = clamp((vt2 - spd) / 4, 0.35, 1); else if (spd > vt2 + 1.2) brake = clamp((spd - vt2) / 6, 0.2, 1);
      if (tp.gap || routeAt(this.route, a.s).gap) { throttle = 1; brake = 0; } // commit to the jump
      if (nos) { throttle = 1; brake = 0; }
      V.update(dt, { throttle, brake, steer, handbrake: false, nos });
      // stuck / lost recovery (also: fell off a deck)
      if (spd < 1.5 || q.d > 22 || V.inWater > 0.5 || (V.onGround && q.dy < -8)) a.stuck += dt; else a.stuck = Math.max(0, a.stuck - dt);
      if (a.stuck > 2.2) { let s0 = a.s + 2; while (routeAt(this.route, s0).gap || routeAt(this.route, s0 + 25).gap) s0 -= 10; const r0 = routeAt(this.route, s0); V.reset(r0.x - r0.tz * a.lane, r0.z + r0.tx * a.lane, Math.atan2(r0.tx, r0.tz), r0.y); a.stuck = 0; }
      if (a.s >= L - 3 && !a.finished) { a.finished = true; a.time = this.t; }
    }
