    await new Promise(r => requestAnimationFrame(() => setTimeout(r, 30)));
    initCarMaterials(); initLowMats();
    this.env = setupScene(renderer, this.quality);
    this.scene = this.env.scene;
    let tod = 'golden', wx = 'clear'; try { tod = localStorage.getItem('m67-tod') || 'golden'; wx = localStorage.getItem('m67-wx') || 'clear'; } catch (e) { }
    applyLighting(this.env, LIGHTING[tod] ? tod : 'golden', WEATHER[wx] ? wx : 'clear');
    Post.init(renderer); Post.enabled = this.quality === 'high';
    $('ld-t').textContent = 'Building the island…';
    await new Promise(r => setTimeout(r, 20));
    buildWorld(this.scene, this.quality);
    applyLighting(this.env, this.env.preset);
    // the car
    const mesh = buildHQCar({ color: 0xbc0b51 });
    mesh.traverse(o => { if (o.isMesh) o.castShadow = true; });
    this.scene.add(mesh);
    this.player = new Vehicle(mesh);
    Upgrades.load(); Upgrades.apply(this.player); Champ.load();
