    const tp = routeAt(Race.route, Race.playerS + 7 + P.speed * 0.5);
    const dx = tp.x - P.pos.x, dz = tp.z - P.pos.z;
    const fwd = dx * Math.sin(P.heading) + dz * Math.cos(P.heading), left = dx * Math.cos(P.heading) - dz * Math.sin(P.heading);
