      let best = inSky ? PLACES.find(pl => pl.deck && P.onDeck && P.onDeck.id === pl.deck) || (P.onMoon || (P.onDeck && P.onDeck.id === 'moontrack') ? PLACES.find(pl => pl.moon) : null) : null, bd = Infinity;
      if (!best) for (const pl of PLACES) { if (!!pl.sky !== inSky || pl.deck) continue; const d = Math.hypot(pl.x - P.pos.x, pl.z - P.pos.z) / pl.r; if (d < 1 && d < bd) { bd = d; best = pl; } }
